header_cache_t* open_header_cache(struct ImapData *idata, const char *path) {
    char *resolved_path = NULL;
    header_cache_t *cache = NULL;

    // Use provided path if it's valid; otherwise derive from context
    if (!path) {
        // Assume idata->mailbox holds the mailbox URL path or similar
        if (!idata || !idata->mailbox) {
            return NULL;
        }

        // Construct the cache path from the ImapData context
        resolved_path = malloc(strlen(idata->mailbox) + 16); // 16 for appending cache suffix
