header_cache_t* open_header_cache(struct ImapData *idata, const char *path) {
    char *full_path = NULL;
    header_cache_t *cache = NULL;

    if (!idata) {
        return NULL;
    }

    if (!path) {
        // Derive path from ImapData context
        if (!idata->context || !idata->context->cache_dir) {
            return NULL;
        }

        full_path = malloc(strlen(idata->context->cache_dir) + strlen("/headers") + 1);
        if (!full_path) {
            return NULL;
        }

        snprintf(full_path, strlen(idata->context->cache_dir) + strlen("/headers") + 1,
                 "%s/headers", idata->context->cache_dir);
        path = full_path;
    }

    // Validate the path for unsafe patterns
    if (strstr(path, "..") || strstr(path, ":")) {
        if (full_path) {
            free(full_path);
        }
        return NULL;
    }

    // Convert the URL and open the header cache
    cache = header_cache_open(path);
    if (!cache) {
        if (full_path) {
            free(full_path);
        }
    }

    if (full_path) {
        free(full_path);
    }

    return cache;
}
